std::once_flag once;                     // per cell, never reset
std::atomic<Config*> cfg{nullptr};

Config& config() {
    Config* c = cfg.load(std::memory_order_acquire);
    if (!c) {
        std::call_once(once, [] {
            cfg.store(Config::load(), std::memory_order_release);
        });
        c = cfg.load(std::memory_order_acquire);
    }
    return *c;
}

std::atomic<Config*> cfg{nullptr};
std::mutex init_mutex;

Config& config() {
    Config* c = cfg.load(std::memory_order_acquire);      // fast path
    if (!c) {
        std::lock_guard<std::mutex> guard(init_mutex);
        c = cfg.load(std::memory_order_relaxed);          // lock orders it
        if (!c) { c = Config::load(); cfg.store(c, std::memory_order_release); }
    }
    return *c;
}
